"""Export explicit backend source/evidence only; no virtualenv or credentials."""

import hashlib
import json
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / ".local" / "deliverables"


def main():
    OUT.mkdir(exist_ok=True)
    paths = {ROOT / name for name in (
        "README.md", "AGENTS.md", ".editorconfig", ".gitattributes", ".gitignore",
        "backend/pyproject.toml", "backend/requirements-lock.txt", "backend/.env.example",
    )}
    for folder in ("backend/src", "backend/scripts", "backend/tests", "docs"):
        for path in (ROOT / folder).rglob("*"):
            if path.is_file() and not {"__pycache__", ".pytest_cache", ".ruff_cache"}.intersection(path.parts):
                paths.add(path)
    for name in (
        "completion_audit.py", "completion_supplemental_audit.py", "completion_thread_read_audit.py",
        "run_capability_current.py", "build_completion_handoff.py", "export_backend_handoff.py",
    ):
        paths.add(ROOT / ".local/superagent" / name)
    # Raw closed evidence is copied as bytes; neither Store nor SQLite is opened.
    closed = ROOT / ".local/superagent/20261116T055126Z-capability-continuity-f87e7e"
    for folder in (closed / "data", closed / "inputs", closed / "work"):
        for path in folder.rglob("*"):
            if path.is_file() and not {"worker-environments", "__pycache__"}.intersection(path.parts):
                paths.add(path)
    snapshot = ROOT / ".local/superagent/f87e7e-independent-frozen-source"
    paths.update(path for path in snapshot.rglob("*") if path.is_file())
    manifest = []
    for path in sorted(paths):
        data = path.read_bytes()
        manifest.append({"path": path.relative_to(ROOT).as_posix(), "bytes": len(data),
                         "sha256": hashlib.sha256(data).hexdigest()})
    archive = OUT / "FORGE-backend-handoff-20261116.zip"
    with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED) as handle:
        for item in manifest:
            handle.write(ROOT / item["path"], item["path"])
        handle.writestr("BACKEND-HANDOFF-MANIFEST.json", json.dumps({
            "scope": "Backend working source, reports, closed latest-run evidence and handoff. Merge into a full workspace; desktop, Git history, virtualenv and Provider secrets are excluded.",
            "entrypoint": "docs/SUPERAGENT_NEXT_ENV_HANDOFF.md", "files": manifest,
        }, ensure_ascii=False, indent=2) + "\n")
    with zipfile.ZipFile(archive) as handle:
        assert handle.testzip() is None
        for item in manifest:
            assert hashlib.sha256(handle.read(item["path"])).hexdigest() == item["sha256"]
    checksum = hashlib.sha256(archive.read_bytes()).hexdigest()
    archive.with_suffix(".zip.sha256").write_text(checksum + "  " + archive.name + "\n", encoding="utf-8")
    print(json.dumps({"archive": str(archive), "files": len(manifest),
                      "bytes": archive.stat().st_size, "sha256": checksum,
                      "all_member_hashes_verified": True}))


if __name__ == "__main__":
    main()

